INSERT INTO site_areas (slug,area_type,country_code,name_ar,name_en,name_fr,currency_code,currency_symbol) VALUES ('argentina','country','AR','الأرجنتين','Argentina','Argentine','ARS','ARS') ON CONFLICT (slug) DO UPDATE SET name_ar=EXCLUDED.name_ar,name_en=EXCLUDED.name_en,currency_code='ARS',currency_symbol='ARS',is_active=TRUE,updated_at=NOW();
INSERT INTO area_content (area_id,content_key,content_ar,content_en,content_type,section,sort_order) SELECT id,v.k,v.ar,v.en,'text',v.s,v.o FROM site_areas JOIN (VALUES ('seo_title','تحفيظ قرآن أونلاين في الأرجنتين | أكاديمية الحافظ','Online Quran and Arabic learning in Argentina','seo',0),('seo_description','تحفيظ القرآن ومراجعة القرآن بالعربية وتأسيس العربية أونلاين للناطقين بالعربية في الأرجنتين، مع أسعار بالبيزو الأرجنتيني.','Online Quran memorization, Arabic Quran review and Arabic foundations for Arabic-speaking learners in Argentina, with ARS prices.','seo',1),('local_card','Al-Hafiz Academy offers individual online Quran memorization and Arabic foundations for Arabic-speaking learners in Argentina. Buenos Aires, Cordoba, Rosario and Mendoza are geographic references for this page. Learning is online, communication is in Arabic, and there is no local office, branch or teaching location in Argentina.','Individual Quran and Arabic learning online for Arabic-speaking learners in Argentina.','local',0)) v(k,ar,en,s,o) ON site_areas.slug='argentina' ON CONFLICT (area_id,content_key) DO UPDATE SET content_ar=EXCLUDED.content_ar,content_en=EXCLUDED.content_en,is_active=TRUE;
INSERT INTO area_packages (area_id,program,package_key,name_ar,name_en,description_ar,price,currency_code,sessions_per_month,is_active,sort_order) SELECT id,v.p,v.k,v.n,v.n,v.d,v.price,'ARS',v.sessions,TRUE,v.o FROM site_areas JOIN (VALUES ('quran','quran-4','تحفيظ القرآن — 4 حصص','Quran memorization',22871,'حفظ ومراجعة فردية',4,0),('quran','quran-8','تحفيظ القرآن — 8 حصص','Quran memorization',42693,'حفظ ومراجعة فردية',8,1),('quran','quran-12','تحفيظ القرآن — 12 حصة','Quran memorization',64039,'حفظ ومراجعة فردية',12,2),('quran','quran-16','تحفيظ القرآن — 16 حصة','Quran memorization',83861,'حفظ ومراجعة فردية',16,3),('arabic','arabic-4','تأسيس العربية — 4 حصص','Arabic foundations',30495,'قراءة وفهم',4,0),('arabic','arabic-8','تأسيس العربية — 8 حصص','Arabic foundations',54891,'قراءة وفهم',8,1),('arabic','arabic-12','تأسيس العربية — 12 حصة','Arabic foundations',82336,'قراءة وفهم',12,2),('arabic','arabic-16','تأسيس العربية — 16 حصة','Arabic foundations',109782,'قراءة وفهم',16,3)) v(p,k,n,d,price,description_text,sessions,o) ON site_areas.slug='argentina' ON CONFLICT (area_id,package_key) DO UPDATE SET price=EXCLUDED.price,name_ar=EXCLUDED.name_ar,program=EXCLUDED.program,is_active=TRUE;
INSERT INTO area_faq_items (area_id,question_key,question_ar,question_en,answer_ar,answer_en,sort_order) SELECT id,v.k,v.q,v.q,v.a,v.a,v.o FROM site_areas JOIN (VALUES ('ar-1','كيف تبدأ الدراسة من الأرجنتين؟','تبدأ الدراسة أونلاين بذكر الهدف والمستوى والوقت المناسب، ثم تُرتب الحصة التجريبية المجانية.',0),('ar-2','هل الأسعار بالبيزو الأرجنتيني؟','نعم، الأسعار الظاهرة في صفحة الأرجنتين بالبيزو الأرجنتيني.',1),('ar-3','ما مدة الحصة الأساسية؟','مدة الحصة الأساسية المعروضة 30 دقيقة.',2),('ar-4','بأي لغة يتم التواصل؟','يتم التواصل مع الأكاديمية باللغة العربية.',3),('ar-5','هل توجد باقات مخصصة؟','يوجد باقات مخصصة.',4)) v(k,q,a,o) ON site_areas.slug='argentina' ON CONFLICT (area_id,question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar,answer_ar=EXCLUDED.answer_ar,is_active=TRUE;
INSERT INTO area_links (area_id,link_key,label_ar,label_en,href,link_type,is_external,sort_order) SELECT id,v.k,v.l,v.l,v.h,v.t,v.x,v.o FROM site_areas JOIN (VALUES ('canonical','الصفحة الرسمية','https://quran-elhafez.com/argentina','canonical',TRUE,0),('whatsapp','واتساب','https://bit.ly/4aJfOl6','external',TRUE,1),('home','الرئيسية','/','internal',FALSE,2),('games','الألعاب والمسابقات','/games','internal',FALSE,3),('library','المكتبة','/library','internal',FALSE,4)) v(k,l,h,t,x,o) ON site_areas.slug='argentina' ON CONFLICT (area_id,link_key) DO UPDATE SET href=EXCLUDED.href,label_ar=EXCLUDED.label_ar,is_active=TRUE;
INSERT INTO area_themes (area_id,theme_name_ar,theme_name_en,primary_color,secondary_color,accent_color,background_color,text_color) SELECT id,'دفتر موسيقى الأرجنتين','Argentina music notebook','#0284C7','#F59E0B','#E0F2FE','#F8FAFC','#0F172A' FROM site_areas WHERE slug='argentina' ON CONFLICT (area_id) DO UPDATE SET primary_color=EXCLUDED.primary_color,secondary_color=EXCLUDED.secondary_color,accent_color=EXCLUDED.accent_color,background_color=EXCLUDED.background_color,text_color=EXCLUDED.text_color,is_active=TRUE;
INSERT INTO area_cities (area_id,city_key,name_ar,name_en,region_name,sort_order) SELECT id,v.k,v.a,v.e,v.r,v.o FROM site_areas JOIN (VALUES ('buenos-aires','بوينس آيرس','Buenos Aires','Buenos Aires',10),('cordoba','قرطبة','Cordoba','Cordoba',20),('rosario','روساريو','Rosario','Santa Fe',30),('mendoza','مندوزا','Mendoza','Mendoza',40)) v(k,a,e,r,o) ON site_areas.slug='argentina' ON CONFLICT (area_id,city_key) DO UPDATE SET name_ar=EXCLUDED.name_ar,name_en=EXCLUDED.name_en,is_active=TRUE;
INSERT INTO area_timezones (area_id,timezone_name,label_ar,label_en,is_primary,sort_order) SELECT id,'America/Argentina/Buenos_Aires','توقيت الأرجنتين (America/Argentina/Buenos_Aires)','Argentina Time',TRUE,10 FROM site_areas WHERE slug='argentina' ON CONFLICT (area_id,timezone_name) DO UPDATE SET label_ar=EXCLUDED.label_ar,is_primary=TRUE,is_active=TRUE;
